script:
// Load API status function
function loadApiStatus() {
  frappe.call({
    method: 'right_hire.right_hire.api_status_dashboard.get_api_status_html',
    callback: function(r) {
      if (r.message) {
        root_element.querySelector('#api-status-container').innerHTML = r.message;
      } else {
        root_element.querySelector('#api-status-container').innerHTML = '<div style="padding: 15px; background: #f8f9fa; border-radius: 8px;"><p style="color: #6c757d; margin: 0;">Unable to load API status.</p></div>';
      }
    }
  });
}

loadApiStatus();
setInterval(loadApiStatus, 60000);

function handleSyncButton(target, action, method, label) {
  target.disabled = true;
  target.textContent = 'Syncing...';

  frappe.call({
    method: method,
    freeze: false,
    callback: function(r) {
      var res = r.message || {};
      if (res.status === 'error') {
        frappe.show_alert({ message: label + ' sync failed: ' + (res.message || 'Unknown error'), indicator: 'red' }, 7);
      } else {
        var msg = label + ' sync complete';
        if (res.new_transactions !== undefined) msg += ' — ' + res.new_transactions + ' new';
        else if (res.new_fines !== undefined) msg += ' — ' + res.new_fines + ' new';
        else if (res.new_trips !== undefined) msg += ' — ' + res.new_trips + ' new';
        frappe.show_alert({ message: msg, indicator: 'green' }, 5);
      }
      var btn = root_element.querySelector('[data-action="' + action + '"]');
      if (btn) { btn.disabled = false; btn.textContent = 'Sync ' + label; }
      loadApiStatus();
    },
    error: function(r) {
      var errMsg = 'Request failed';
      if (r && r.responseJSON && r.responseJSON._server_messages) {
        try { errMsg = JSON.parse(JSON.parse(r.responseJSON._server_messages)[0]).message; } catch(e) {}
      }
      frappe.show_alert({ message: label + ' sync error: ' + errMsg, indicator: 'red' }, 7);
      var btn = root_element.querySelector('[data-action="' + action + '"]');
      if (btn) { btn.disabled = false; btn.textContent = 'Sync ' + label; }
    }
  });
}

root_element.addEventListener('click', function(e) {
  var target = e.target;

  if (target.matches('[data-action="refresh-status"]')) {
    e.preventDefault();
    target.disabled = true;
    target.textContent = '...';
    loadApiStatus();
    setTimeout(function() {
      var btn = root_element.querySelector('[data-action="refresh-status"]');
      if (btn) { btn.disabled = false; btn.textContent = '\u21bb'; }
    }, 1000);
  }

  if (target.matches('[data-action="sync-salik"]')) {
    e.preventDefault();
    handleSyncButton(target, 'sync-salik', 'right_hire.right_hire.api_status_dashboard.sync_salik_now', 'Salik');
  }

  if (target.matches('[data-action="sync-darb"]')) {
    e.preventDefault();
    handleSyncButton(target, 'sync-darb', 'right_hire.right_hire.api_status_dashboard.sync_darb_now', 'Darb');
  }

  if (target.matches('[data-action="sync-rta"]')) {
    e.preventDefault();
    handleSyncButton(target, 'sync-rta', 'right_hire.right_hire.api_status_dashboard.sync_rta_fines_now', 'RTA');
  }
});

style:
.api-loading {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px;
  background: #f8f9fa;
  border-radius: 8px;
  color: #6c757d;
}

.api-loading .spinner-border {
  width: 20px;
  height: 20px;
}
